import { Request, Response } from 'express';
import { PlaceOrderUseCase } from '../../application/usecases/PlaceOrderUseCase';
import { CancelOrderUseCase } from '../../application/usecases/CancelOrderUseCase';
import { UpdateOrderStatusUseCase } from '../../application/usecases/UpdateOrderStatusUseCase';
import { ListOrdersByStatusUseCase } from '../../application/usecases/ListOrdersByStatusUseCase';
import { GetStockLevelsUseCase } from '../../application/usecases/GetStockLevelsUseCase';
import { OrderStatus } from '../../domain/entities/Order';

export class OrderController {
  constructor(
    private placeOrderUseCase: PlaceOrderUseCase,
    private cancelOrderUseCase: CancelOrderUseCase,
    private updateOrderStatusUseCase: UpdateOrderStatusUseCase,
    private listOrdersByStatusUseCase: ListOrdersByStatusUseCase,
    private getStockLevelsUseCase: GetStockLevelsUseCase
  ) {}

  placeOrder = (req: Request, res: Response): void => {
    try {
      const dto = this.placeOrderUseCase.execute(req.body);
      res.status(201).json(dto);
    } catch (error) {
      this.handleError(error, res);
    }
  };

  cancelOrder = (req: Request, res: Response): void => {
    try {
      const orderId = Array.isArray(req.params.orderId) ? req.params.orderId[0] : req.params.orderId;
      const dto = this.cancelOrderUseCase.execute(orderId);
      res.json(dto);
    } catch (error) {
      this.handleError(error, res);
    }
  };

  updateOrderStatus = (req: Request, res: Response): void => {
    try {
      const orderId = Array.isArray(req.params.orderId) ? req.params.orderId[0] : req.params.orderId;
      const dto = this.updateOrderStatusUseCase.execute(orderId, req.body);
      res.json(dto);
    } catch (error) {
      this.handleError(error, res);
    }
  };

  listOrdersByStatus = (req: Request, res: Response): void => {
    try {
      const { status } = req.query;
      if (!status || typeof status !== 'string') {
        res.status(400).json({ error: 'Status query parameter is required' });
        return;
      }

      const validStatuses: OrderStatus[] = ['placed', 'paid', 'packed', 'shipped', 'delivered'];
      if (!validStatuses.includes(status as OrderStatus)) {
        res.status(400).json({ error: `Invalid status: ${status}` });
        return;
      }

      const dtos = this.listOrdersByStatusUseCase.execute(status as OrderStatus);
      res.json(dtos);
    } catch (error) {
      this.handleError(error, res);
    }
  };

  getStockLevels = (req: Request, res: Response): void => {
    try {
      const dtos = this.getStockLevelsUseCase.execute();
      res.json(dtos);
    } catch (error) {
      this.handleError(error, res);
    }
  };

  private handleError(error: unknown, res: Response): void {
    const message = error instanceof Error ? error.message : 'Unknown error';
    res.status(400).json({ error: message });
  }
}

